INSERT INTO `tournament_match_summaries` (`id`,`event_id`,`round`,`best_of`,`leader_one_code`,`archetype_one`,`leader_two_code`,`archetype_two`,`score_one`,`score_two`,`winner_leader_code`,`winner_side`,`summary`,`source_name`,`source_url`,`evidence_status`) VALUES
('utrecht-2026-top8-enel-mihawk','utrecht-eu-finals-2026','Top 8',3,'OP15-058','Purple Enel','OP14-020','Green Dracule Mihawk',2,1,'OP15-058',1,'Purple Enel wins 2–1 in a close Top 8 series. Game 1: Enel opens slowly, then develops Shura, M, and Holly into double-attack pressure. Mihawk misses key Samurai and six-cost plays, makes an unfavorable attack into M, and concedes when the hand cannot recover. Game 2: Mihawk goes first and stabilizes through Kin’emon, Samurai, Law, Perona, 10-cost Shanks, and Electrical Luna. Enel sets up Shura and a pumped leader, but Mihawk defends with Trichiliocosm and counters, then Shanks rests Enel’s board and Mihawk closes with large attacks. Game 3: Enel has early M and Holly, uses Law hand-rip to hit Mihawk’s key cards, and follows with Senior Pink, Gamma Knife, and El Thor to remove blockers and keep Mihawk low on life. Mihawk stabilizes with Law and Oden, then plays 10-cost Shanks to rest Enel’s field and threaten lethal. Enel answers with Mamaragan, Kiten, Veri, El Thor, Gamma Knife, and Law to remove blockers and preserve counter. Enel rebuilds with Shura and uses Luna and Law to strand Mihawk without blockers; Mihawk survives the first key attack with Trichiliocosm and counters but cannot cover the final attack. Enel wins game 3 and advances to Top 4.','User-confirmed video analysis summary','https://www.youtube.com/watch?v=qgwRa20C3lE','VERIFIED');
